//! Verifies the zero-sized modulus context generated by `#[derive(Barrett)]`.

#![cfg(feature = "derive")]

use primus_modulus::Barrett;

#[derive(Barrett)]
#[modulus(ty = u32, value = 536813569)]
struct Modulus;

/// Generated constants cover word widths, power-of-two fallback, and both sides of the IFMA limit.
#[test]
fn derived_multiply_add_matches_wide_remainders() {
    use primus_reduce::ReduceMulAddSlice;

    macro_rules! check {
        ($ty:ty, $q:literal) => {{
            #[derive(Barrett)]
            #[modulus(ty = $ty, value = $q)]
            struct FixedModulus;

            for len in [0, 1, 7, 17, 31, 32, 33, 65] {
                let mut state = 42u64;
                let mut sample = |i| {
                    state ^= state << 13;
                    state ^= state >> 7;
                    state ^= state << 17;
                    match i % 5 {
                        0 => 0,
                        1 => $q - 1,
                        _ => (state % ($q as u64)) as $ty,
                    }
                };
                let lhs: Vec<$ty> = (0..len).map(&mut sample).collect();
                let rhs: Vec<$ty> = (0..len).map(|i| sample(i + 1)).collect();
                let mut expected: Vec<$ty> = (0..len).map(|i| sample(i + 2)).collect();
                let mut guarded = vec![<$ty>::MAX; len + 2];
                let mut output = vec![<$ty>::MAX; len + 2];
                guarded[1..len + 1].copy_from_slice(&expected);
                // A second call checks reuse of a canonical accumulator.
                for _ in 0..2 {
                    for ((c, &a), &b) in expected.iter_mut().zip(&lhs).zip(&rhs) {
                        *c = ((*c as u128 + a as u128 * b as u128) % ($q as u128)) as $ty;
                    }
                    FixedModulus.reduce_mul_add_slice_to(
                        &lhs,
                        &rhs,
                        &guarded[1..len + 1],
                        &mut output[1..len + 1],
                    );
                    FixedModulus.reduce_add_mul_slice_assign(&mut guarded[1..len + 1], &lhs, &rhs);
                    assert_eq!(&guarded[1..len + 1], expected, "q={}, len={len}", $q as u64);
                    assert_eq!(
                        &output[1..len + 1],
                        expected,
                        "to: q={}, len={len}",
                        $q as u64
                    );
                    assert_eq!(guarded[0], <$ty>::MAX);
                    assert_eq!(guarded[len + 1], <$ty>::MAX);
                    assert_eq!(output[0], <$ty>::MAX);
                    assert_eq!(output[len + 1], <$ty>::MAX);
                    output[1..len + 1].fill(<$ty>::MAX);
                }
            }
        }};
    }

    check!(u16, 12289);
    check!(u32, 132120577);
    check!(u32, 536870912);
    check!(u64, 1125899906826241);
    check!(u64, 281474976710656);
    check!(u64, 1125899906842624);
    check!(u64, 1125899906842625);
    check!(u64, 4611686018427387903);
}

#[cfg(all(test, feature = "derive"))]
mod u32tests {
    use primus_reduce::FieldContext;
    use primus_reduce::prelude::*;
    use rand::{SeedableRng, distr::Uniform, prelude::*, rngs::StdRng};

    use super::Modulus;

    type ValueT = u32;
    const SEED: u64 = 0x4445_5249_5645_5331;

    fn field_trait<M: FieldContext<ValueT>>(_modulus: M) {}

    fn mul_mod(a: u32, b: u32) -> u32 {
        ((a as u64 * b as u64) % Modulus::value() as u64) as u32
    }

    /// Check generated arithmetic with wide scalar oracles and inverse/division identities.
    #[test]
    fn scalar_ops() {
        field_trait(Modulus);
        let m = Modulus::value();
        let distr = Uniform::new(0, m).unwrap();
        let mut rng = StdRng::seed_from_u64(SEED);
        let a = distr.sample(&mut rng);
        let b = distr.sample(&mut rng);
        let c = distr.sample(&mut rng);

        assert_eq!(Modulus.reduce_add(a, b), (a + b) % m);
        assert_eq!(Modulus.reduce_sub(a, b), (a + m - b) % m);
        assert_eq!(0, Modulus.reduce_add(a, Modulus.reduce_neg(a)));
        assert_eq!(Modulus.reduce_mul(a, b), mul_mod(a, b));
        assert_eq!(Modulus.reduce_square(a), mul_mod(a, a));
        assert_eq!(
            Modulus.reduce_mul_add(a, b, c),
            ((a as u64 * b as u64 + c as u64) % m as u64) as u32
        );
        if a != 0 {
            assert_eq!(1, Modulus.reduce_mul(a, Modulus.reduce_inv(a)));
        }
        if b != 0 {
            assert_eq!(a, Modulus.reduce_mul(b, Modulus.reduce_div(a, b)));
        }
    }

    /// An empty multi-limb input has no value for the generated lazy-reduction contract.
    #[test]
    #[should_panic(expected = "Barrett reduction requires at least one limb")]
    fn lazy_reduce_empty_slice_panics() {
        let _ = Modulus.lazy_reduce(&[] as &[u32]);
    }

    /// Generated slice methods retain their own coverage because they are emitted separately.
    #[test]
    fn slice_ops() {
        use primus_modulus::BarrettModulus;

        let m = Modulus::value();
        let distr = Uniform::new(0, m).unwrap();
        let mut rng = StdRng::seed_from_u64(SEED ^ 1);

        for &len in &[0usize, 17] {
            let a: Vec<u32> = distr.sample_iter(&mut rng).take(len).collect();
            let b: Vec<u32> = distr.sample_iter(&mut rng).take(len).collect();
            let c: Vec<u32> = distr.sample_iter(&mut rng).take(len).collect();
            let scalar: u32 = distr.sample(&mut rng);

            let once_in: Vec<u32> = a
                .iter()
                .map(|&x| {
                    if rng.random_bool(0.5) {
                        x
                    } else {
                        x.wrapping_add(m)
                    }
                })
                .collect();
            let mut assign = once_in.clone();
            Modulus.reduce_once_slice_assign(&mut assign);
            assert_eq!(assign, a, "once_slice_assign len={len}");

            let mut add = a.clone();
            Modulus.reduce_add_slice_assign(&mut add, &b);
            let add_exp: Vec<u32> = a.iter().zip(&b).map(|(&x, &y)| (x + y) % m).collect();
            assert_eq!(add, add_exp, "add_slice_assign len={len}");

            let mut sub = a.clone();
            Modulus.reduce_sub_slice_assign(&mut sub, &b);
            let sub_exp: Vec<u32> = a
                .iter()
                .zip(&b)
                .map(|(&x, &y)| if x >= y { x - y } else { x + m - y })
                .collect();
            assert_eq!(sub, sub_exp, "sub_slice_assign len={len}");

            let expected_mul: Vec<u32> = a.iter().zip(&b).map(|(&x, &y)| mul_mod(x, y)).collect();
            let mut mul_a = a.clone();
            Modulus.reduce_mul_slice_assign(&mut mul_a, &b);
            assert_eq!(mul_a, expected_mul, "mul_slice_assign len={len}");

            let mut lazy = a.clone();
            Modulus.lazy_reduce_mul_slice_assign(&mut lazy, &b);
            for v in lazy.iter_mut() {
                assert!(*v < m * 2);
                if *v >= m {
                    *v -= m;
                }
            }
            assert_eq!(lazy, expected_mul, "lazy_mul_slice_assign len={len}");

            let mut acc = c.clone();
            Modulus.reduce_add_mul_slice_assign(&mut acc, &a, &b);
            let acc_exp: Vec<u32> = c
                .iter()
                .zip(&a)
                .zip(&b)
                .map(|((&z, &x), &y)| ((x as u64 * y as u64 + z as u64) % m as u64) as u32)
                .collect();
            assert_eq!(acc, acc_exp, "add_mul_slice_assign len={len}");

            let mut out = vec![0; len];
            Modulus.reduce_mul_add_slice_to(&a, &b, &c, &mut out);
            assert_eq!(out, acc_exp, "mul_add_slice_to len={len}");

            let expected_scalar: Vec<u32> = a.iter().map(|&x| mul_mod(x, scalar)).collect();
            let mut s_mul = a.clone();
            Modulus.reduce_mul_scalar_slice_assign(&mut s_mul, scalar);
            assert_eq!(s_mul, expected_scalar, "scalar_mul_slice_assign len={len}");

            let mut out = vec![0; len];
            Modulus.reduce_mul_scalar_add_slice_to(&b, scalar, &c, &mut out);
            let sbc_exp: Vec<u32> = b
                .iter()
                .zip(&c)
                .map(|(&y, &z)| ((scalar as u64 * y as u64 + z as u64) % m as u64) as u32)
                .collect();
            assert_eq!(out, sbc_exp, "scalar_mul_add_slice_to len={len}");

            let expected = {
                let ref_m = BarrettModulus::<u32>::new(m);
                ref_m.reduce_dot_product(&a, &b)
            };
            assert_eq!(
                Modulus.reduce_dot_product(&a, &b),
                expected,
                "dot_product len={len}"
            );
            assert_eq!(
                Modulus.reduce_dot_product_iter(a.iter().copied(), b.iter().copied()),
                expected,
                "dot_product_iter len={len}"
            );
        }
    }

    /// Generated batch inversion agrees with the runtime Barrett context.
    #[test]
    fn inverse_slice_ops() {
        use primus_modulus::BarrettModulus;

        let input = [1, 2, 3, 17, 257];
        let mut expected = [0; 5];
        BarrettModulus::new(Modulus::value()).reduce_inv_slice_to(&input, &mut expected);

        let mut output = [u32::MAX; 5];
        Modulus.reduce_inv_slice_to(&input, &mut output);
        assert_eq!(output, expected);

        output.fill(u32::MAX);
        Modulus
            .try_reduce_inv_slice_to(&input, &mut output)
            .unwrap();
        assert_eq!(output, expected);
    }
}
